import{_ as n,a0 as l,w as p,s as d,I as e,x as i,a1 as a,A as o,ao as r}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const B=JSON.parse('{"title":"Bootiso ：讓你安全地創建 USB 啓動設備 | LCTT x X-CMD","titleTemplate":false,"description":"Bootiso ：讓你安全地創建 USB 啓動設備 | LCTT (201805) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Bootiso ：讓你安全地創建 USB 啓動設備 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Bootiso ：讓你安全地創建 USB 啓動設備 | LCTT (201805) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201805/20180410 Bootiso Lets You Safely Create Bootable USB Drive","title":"Bootiso ：讓你安全地創建 USB 啓動設備","tag":"201805","desc":""},"relativePath":"201805/20180410 Bootiso Lets You Safely Create Bootable USB Drive.md","filePath":"[post].md"}'),b={name:"201805/20180410 Bootiso Lets You Safely Create Bootable USB Drive.md"};function h(g,s,c,u,k,f){const t=l("Link");return p(),d("div",null,[s[30]||(s[30]=e("h1",{id:"bootiso-讓你安全地創建-usb-啓動設備",tabindex:"-1"},[i("Bootiso ：讓你安全地創建 USB 啓動設備 "),e("a",{class:"header-anchor",href:"#bootiso-讓你安全地創建-usb-啓動設備","aria-label":"Permalink to “Bootiso ：讓你安全地創建 USB 啓動設備”"},"​")],-1)),s[31]||(s[31]=e("p",null,[e("img",{src:"https://www.ostechnix.com/wp-content/uploads/2018/04/USB-drive-720x340.png",alt:""})],-1)),e("p",null,[s[1]||(s[1]=i("你好，新兵！你們有些人經常使用 ",-1)),s[2]||(s[2]=e("code",null,"dd",-1)),s[3]||(s[3]=i(" 命令做各種各樣的事，比如創建 USB 啓動盤或者克隆硬盤分區。不過請牢記，",-1)),s[4]||(s[4]=e("code",null,"dd",-1)),s[5]||(s[5]=i(" 是一個危險且有毀滅性的命令。如果你是個 Linux 的新手，最好避免使用 ",-1)),s[6]||(s[6]=e("code",null,"dd",-1)),s[7]||(s[7]=i(" 命令。如果你不知道你在做什麼，你可能會在幾分鐘裏把硬盤擦掉。從原理上説，",-1)),s[8]||(s[8]=e("code",null,"dd",-1)),s[9]||(s[9]=i(" 只是從 ",-1)),s[10]||(s[10]=e("code",null,"if",-1)),s[11]||(s[11]=i(" 讀取然後寫到 ",-1)),s[12]||(s[12]=e("code",null,"of",-1)),s[13]||(s[13]=i(" 上。它才不管往哪裏寫呢。它根本不關心那裏是否有分區表、引導區、家目錄或是其他重要的東西。你叫它做什麼它就做什麼。可以使用像 ",-1)),a(t,{href:"https://www.ostechnix.com/etcher-beauitiful-app-create-bootable-sd-cards-usb-drives/"},{default:o(()=>[...s[0]||(s[0]=[i("Etcher",-1)])]),_:1}),s[14]||(s[14]=i(" 這樣的用户友好的應用來代替它。這樣你就可以在創建 USB 引導設備之前知道你將要格式化的是哪塊盤。",-1))]),s[32]||(s[32]=r(`<p>今天，我發現了另一個可以安全創建 USB 引導設備的工具 Bootiso 。它實際上是一個 BASH 腳本，但真的很智能！它有很多額外的功能來幫我們安全創建 USB 引導盤。如果你想確保你的目標是 USB 設備（而不是內部驅動器），或者如果你想檢測 USB 設備，你可以使用 Bootiso。下面是使用此腳本的顯著優點:</p><ul><li>如果只有一個 USB 驅動器，Bootiso 會自動選擇它。</li><li>如果有一個以上的 USB 驅動器存在，它可以讓你從列表中選擇其中一個。</li><li>萬一你錯誤地選擇一個內部硬盤驅動器，它將退出而不做任何事情。</li><li>它檢查選定的 ISO 是否具有正確的 MIME 類型。如果 MIME 類型不正確，它將退出。</li><li>它判定所選的項目不是分區，如果判定失敗則退出。</li><li>它將在擦除和對 USB 驅動器分區之前提示用户確認。</li><li>列出可用的 USB 驅動器。</li><li>安裝 syslinux 引導系統 (可選)。</li><li>自由且開源。</li></ul><h3 id="使用-bootiso-安全地創建-usb-驅動器" tabindex="-1">使用 Bootiso 安全地創建 USB 驅動器 <a class="header-anchor" href="#使用-bootiso-安全地創建-usb-驅動器" aria-label="Permalink to “使用 Bootiso 安全地創建 USB 驅動器”">​</a></h3><p>安裝 Bootiso 非常簡單。用這個命令下載最新版本：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ curl -L https://rawgit.com/jsamr/bootiso/latest/bootiso -O</span></span></code></pre></div><p>把下載的文件加到 <code>$PATH</code> 目錄中，比如 <code>/usr/local/bin/</code>。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo cp bootiso /usr/local/bin/</span></span></code></pre></div><p>最後，添加運行權限：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo chmod +x /usr/local/bin/bootiso</span></span></code></pre></div><p>搞定！現在就可以創建 USB 引導設備了。首先，讓我們用命令看看現在有哪些 USB 驅動器：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ bootiso -l</span></span></code></pre></div><p>輸出：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Listing USB drives available in your system:</span></span>
<span class="line"><span>NAME HOTPLUG SIZE STATE TYPE</span></span>
<span class="line"><span>sdb 1 7.5G running disk</span></span></code></pre></div><p>如你所見，我只有一個 USB 驅動器。讓我們繼續通過命令用 ISO 文件創建 USB 啓動盤：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ bootiso bionic-desktop-amd64.iso</span></span></code></pre></div><p>這個命令會提示你輸入 <code>sudo</code> 密碼。輸入密碼並回車來安裝缺失的組件（如果有的話），然後創建 USB 啓動盤。</p><p>輸出：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[...]</span></span>
<span class="line"><span>Listing USB drives available in your system:</span></span>
<span class="line"><span>NAME HOTPLUG SIZE STATE TYPE</span></span>
<span class="line"><span>sdb 1 7.5G running disk</span></span>
<span class="line"><span>Autoselecting \`sdb&#39; (only USB device candidate)</span></span>
<span class="line"><span>The selected device \`/dev/sdb&#39; is connected through USB.</span></span>
<span class="line"><span>Created ISO mount point at \`/tmp/iso.c5m&#39;</span></span>
<span class="line"><span>\`bootiso&#39; is about to wipe out the content of device \`/dev/sdb&#39;.</span></span>
<span class="line"><span>Are you sure you want to proceed? (y/n)&gt;y</span></span>
<span class="line"><span>Erasing contents of /dev/sdb...</span></span>
<span class="line"><span>Creating FAT32 partition on \`/dev/sdb1&#39;...</span></span>
<span class="line"><span>Created USB device mount point at \`/tmp/usb.QgV&#39;</span></span>
<span class="line"><span>Copying files from ISO to USB device with \`rsync&#39;</span></span>
<span class="line"><span>Synchronizing writes on device \`/dev/sdb&#39;</span></span>
<span class="line"><span>\`bootiso&#39; took 303 seconds to write ISO to USB device with \`rsync&#39; method.</span></span>
<span class="line"><span>ISO succesfully unmounted.</span></span>
<span class="line"><span>USB device succesfully unmounted.</span></span>
<span class="line"><span>USB device succesfully ejected.</span></span>
<span class="line"><span>You can safely remove it !</span></span></code></pre></div><p>如果你的 ISO 文件 MIME 類型不對，你會得到下列錯誤信息：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Provided file \`bionic-desktop-amd64.iso&#39; doesn&#39;t seem to be an iso file (wrong mime type: \`application/octet-stream&#39;).</span></span>
<span class="line"><span>Exiting bootiso...</span></span></code></pre></div><p>當然，你也能像下面那樣使用 <code>–no-mime-check</code> 選項來跳過 MIME 類型檢查。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ bootiso --no-mime-check bionic-desktop-amd64.iso</span></span></code></pre></div><p>就像我前面提到的，如果系統裏只有 1 個 USB 設備 Bootiso 將自動選中它。所以我們不需要告訴它 USB 設備路徑。如果你連接了多個設備，你可以像下面這樣使用 <code>-d</code> 來指明 USB 設備。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ bootiso -d /dev/sdb bionic-desktop-amd64.iso</span></span></code></pre></div><p>用你自己的設備路徑來換掉 <code>/dev/sdb</code>。</p><p>在多個設備情況下，如果你沒有使用 <code>-d</code> 來指明要使用的設備，Bootiso 會提示你選擇可用的 USB 設備。</p><p>Bootiso 在擦除和改寫 USB 盤分區前會要求用户確認。使用 <code>-y</code> 或 <code>–assume-yes</code> 選項可以跳過這一步。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ bootiso -y bionic-desktop-amd64.iso</span></span></code></pre></div><p>您也可以把自動選擇 USB 設備與 <code>-y</code> 選項連用，如下所示。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ bootiso -y -a bionic-desktop-amd64.iso</span></span></code></pre></div><p>或者，</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ bootiso?--assume-yes?--autoselect bionic-desktop-amd64.iso</span></span></code></pre></div><p>請記住，當你只連接一個 USB 驅動器時，它才會起作用。</p><p>Bootiso 會默認創建一個 FAT 32 分區，掛載後用 <code>rsync</code> 程序把 ISO 的內容拷貝到 USB 盤裏。 如果你願意也可以使用 <code>dd</code> 代替 <code>rsync</code> 。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ bootiso --dd -d /dev/sdb bionic-desktop-amd64.iso</span></span></code></pre></div><p>如果你想增加 USB 引導的成功概率，請使用 <code>-b</code> 或 <code>–bootloader</code> 選項。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ bootiso -b bionic-desktop-amd64.iso</span></span></code></pre></div><p>上面這條命令會安裝 <code>syslinux</code> 引導程序（安全模式）。注意，此時 <code>–dd</code> 選項不可用。</p><p>在創建引導設備後，Bootiso 會自動彈出 USB 設備。如果不想自動彈出，請使用 <code>-J</code> 或 <code>–no-eject</code> 選項。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ bootiso -J bionic-desktop-amd64.iso</span></span></code></pre></div><p>現在，USB 設備依然連接中。你可以使用 <code>umount</code> 命令隨時卸載它。</p><p>需要完整幫助信息，請輸入：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ bootiso -h</span></span></code></pre></div><p>好，今天就到這裏。希望這個腳本對你有幫助。好貨不斷，不要走開哦！</p><hr>`,45)),e("p",null,[s[16]||(s[16]=i("via: ",-1)),a(t,{href:"https://www.ostechnix.com/bootiso-lets-you-safely-create-bootable-usb-drive/"},{default:o(()=>[...s[15]||(s[15]=[i("https://www.ostechnix.com/bootiso-lets-you-safely-create-bootable-usb-drive/",-1)])]),_:1})]),e("p",null,[s[21]||(s[21]=i("作者：",-1)),a(t,{href:"https://www.ostechnix.com/author/sk/"},{default:o(()=>[...s[17]||(s[17]=[i("SK",-1)])]),_:1}),s[22]||(s[22]=i(" 選題：",-1)),a(t,{href:"https://github.com/lujun9972"},{default:o(()=>[...s[18]||(s[18]=[i("lujun9972",-1)])]),_:1}),s[23]||(s[23]=i(" 譯者：",-1)),a(t,{href:"https://github.com/kennethXia"},{default:o(()=>[...s[19]||(s[19]=[i("kennethXia",-1)])]),_:1}),s[24]||(s[24]=i(" 校對：",-1)),a(t,{href:"https://github.com/wxy"},{default:o(()=>[...s[20]||(s[20]=[i("wxy",-1)])]),_:1})]),e("p",null,[s[27]||(s[27]=i("本文由 ",-1)),a(t,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...s[25]||(s[25]=[i("LCTT",-1)])]),_:1}),s[28]||(s[28]=i(" 原創編譯，",-1)),a(t,{href:"https://linux.cn/"},{default:o(()=>[...s[26]||(s[26]=[i("Linux中國",-1)])]),_:1}),s[29]||(s[29]=i(" 榮譽推出",-1))])])}const S=n(b,[["render",h]]);export{B as __pageData,S as default};
